CREATE SCHEMA analytics;
CREATE TABLE analytics.regions (id uuid PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE analytics.categories (id uuid PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE analytics.customers (id uuid PRIMARY KEY, full_name text NOT NULL, region_id uuid REFERENCES analytics.regions(id));
CREATE TABLE analytics.products (id uuid PRIMARY KEY, name text NOT NULL, category_id uuid REFERENCES analytics.categories(id), unit_price numeric(12,2) NOT NULL);
CREATE TABLE analytics.orders (id uuid PRIMARY KEY, customer_id uuid REFERENCES analytics.customers(id), region_id uuid REFERENCES analytics.regions(id), ordered_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('completed','cancelled','returned')), total_amount numeric(12,2) NOT NULL);
CREATE TABLE analytics.order_items (id uuid PRIMARY KEY, order_id uuid REFERENCES analytics.orders(id), product_id uuid REFERENCES analytics.products(id), quantity int NOT NULL CHECK (quantity > 0), unit_price numeric(12,2) NOT NULL);
CREATE TABLE analytics.payments (id uuid PRIMARY KEY, order_id uuid REFERENCES analytics.orders(id), amount numeric(12,2) NOT NULL, paid_at timestamptz);
CREATE TABLE analytics.returns (id uuid PRIMARY KEY, order_id uuid REFERENCES analytics.orders(id), reason text NOT NULL, returned_at timestamptz NOT NULL);
CREATE TABLE analytics.sales_representatives (id uuid PRIMARY KEY, full_name text NOT NULL, region_id uuid REFERENCES analytics.regions(id));

INSERT INTO analytics.regions VALUES ('10000000-0000-0000-0000-000000000001','North'),('10000000-0000-0000-0000-000000000002','South'),('10000000-0000-0000-0000-000000000003','East'),('10000000-0000-0000-0000-000000000004','West');
INSERT INTO analytics.categories VALUES ('20000000-0000-0000-0000-000000000001','Electronics'),('20000000-0000-0000-0000-000000000002','Home & Living'),('20000000-0000-0000-0000-000000000003','Outdoor'),('20000000-0000-0000-0000-000000000004','Wellness'),('20000000-0000-0000-0000-000000000005','Office');
SELECT setseed(0.4242);
INSERT INTO analytics.customers SELECT ('30000000-0000-0000-0000-' || lpad(i::text,12,'0'))::uuid, 'Customer ' || i, ('10000000-0000-0000-0000-' || lpad((((i-1)%4)+1)::text,12,'0'))::uuid FROM generate_series(1,2000) i;
INSERT INTO analytics.products SELECT ('40000000-0000-0000-0000-' || lpad(i::text,12,'0'))::uuid, 'Product ' || i, ('20000000-0000-0000-0000-' || lpad((((i-1)%5)+1)::text,12,'0'))::uuid, round((15 + random()*485)::numeric,2) FROM generate_series(1,100) i;
INSERT INTO analytics.orders SELECT ('50000000-0000-0000-0000-' || lpad(i::text,12,'0'))::uuid, ('30000000-0000-0000-0000-' || lpad((((i-1)%2000)+1)::text,12,'0'))::uuid, ('10000000-0000-0000-0000-' || lpad((((i-1)%4)+1)::text,12,'0'))::uuid, '2025-12-01'::timestamptz + (i % 365) * interval '1 day', CASE WHEN i % 29 = 0 THEN 'cancelled' WHEN i % 31 = 0 THEN 'returned' ELSE 'completed' END, round((40 + random()*900)::numeric,2) FROM generate_series(1,10000) i;
INSERT INTO analytics.order_items SELECT ('60000000-0000-0000-0000-' || lpad(i::text,12,'0'))::uuid, ('50000000-0000-0000-0000-' || lpad((((i-1)%10000)+1)::text,12,'0'))::uuid, ('40000000-0000-0000-0000-' || lpad((((i-1)%100)+1)::text,12,'0'))::uuid, 1+(i%4), round((15 + random()*485)::numeric,2) FROM generate_series(1,15000) i;
CREATE ROLE analytics_reader LOGIN PASSWORD 'analytics-readonly-local';
GRANT USAGE ON SCHEMA analytics TO analytics_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics TO analytics_reader;
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO analytics_reader;
